        /// <summary>
        /// Initializes a new instance of the <see cref="CreateStandaloneAdRequest" /> class.
        /// </summary>
        [JsonConstructorAttribute]
        protected CreateStandaloneAdRequest() { }
        /// <summary>
        /// Initializes a new instance of the <see cref="CreateStandaloneAdRequest" /> class.
        /// </summary>
        /// <param name="accountId">accountId (required).</param>
        /// <param name="adAccountId">adAccountId (required).</param>
        /// <param name="name">Omitted, the ad is named &#x60;Ad &lt;YYYY-MM-DD HH:MM:SS&gt;&#x60; (UTC) and the response reports it in &#x60;appliedDefaults.name&#x60;..</param>
        /// <param name="campaignName">Meta, Reddit and Google. Exact campaign name; overrides the default &#x60;&lt;name&gt; - Campaign&#x60;. Ignored when the request joins an existing campaign or ad set.  Google: no line breaks and at most 255 characters, checked before calling Google. Names are unique in the Google Ads account, and on Search and Display a taken name is a 400 naming this field..</param>
        /// <param name="adSetName">Exact ad set name. Meta, Reddit and Google (the ad group).  - Overrides the default &#x60;&lt;name&gt; - Ad Set&#x60; (Google Search and Display: &#x60;&lt;name&gt; - Ad Group&#x60;). - Ignored when the request joins an existing ad set (&#x60;adSetId&#x60;). - Google Search and Display only: also works on &#x60;existingCampaignId&#x60;, where the new ad group&#39;s name is returned as &#x60;adSetName&#x60;. No line breaks, at most 255 characters, unique in the campaign (a taken name is a 400 naming this field). - Demand Gen names its ad group with &#x60;demandGen.adGroupName&#x60;, and Performance Max with &#x60;assetGroup.name&#x60;. - For per-ad names on the multi-creative shape, set &#x60;name&#x60; on each &#x60;creatives[]&#x60; entry..</param>
        /// <param name="adName">Meta only. Exact ad name (the single-creative ad object&#39;s name). Overrides the default, which is &#x60;name&#x60;. (For per-ad names on the multi-creative shape, set &#x60;name&#x60; on each &#x60;creatives[]&#x60; entry instead.).</param>
        /// <param name="tracking">tracking.</param>
        /// <param name="goal">The ad&#39;s goal. Available goals vary by platform. When omitted, it is inferred from the ad (see &#x60;appliedDefaults.goal&#x60; in the response); the attach shape inherits it from the ad set.  **Meta**  - &#x60;conversions&#x60;: OUTCOME_SALES. Requires &#x60;promotedObject.pixelId&#x60; and &#x60;promotedObject.customEventType&#x60; with a commerce event (e.g. PURCHASE, START_TRIAL). Alternatives: &#x60;promotedObject.customConversionId&#x60; for a Custom Conversion, or &#x60;customEventType: OTHER&#x60; + &#x60;customEventStr&#x60; for a pixel custom event. - &#x60;lead_conversion&#x60;: OUTCOME_LEADS optimizing website pixel leads. Same pixel and event fields, with a leads-class event (LEAD, SUBMIT_APPLICATION, SCHEDULE, CONTACT) or &#x60;promotedObject.customConversionId&#x60;. Meta gates conversion events by objective, so leads-class events are rejected under &#x60;conversions&#x60;. - &#x60;lead_generation&#x60;: OUTCOME_LEADS with instant forms. Requires &#x60;leadGenFormId&#x60;. &#x60;promotedObject.pageId&#x60; is optional and auto-filled from the connected Page. - &#x60;app_promotion&#x60;: requires &#x60;promotedObject.applicationId&#x60; and &#x60;promotedObject.objectStoreUrl&#x60;. - &#x60;catalog_sales&#x60;: Advantage+ catalog ads (e.g. vehicle inventory). Requires &#x60;promotedObject.productSetId&#x60;, &#x60;promotedObject.pixelId&#x60; and &#x60;promotedObject.customEventType&#x60;. Builds a catalog TEMPLATE creative from the copy fields, which may carry template tags like {{product.name}} or {{vehicle.make}}. - &#x60;catalog_sales&#x60; visuals: no imageUrl or video is sent; Meta renders them per catalog item (an imageUrl or video sent is ignored, not uploaded). Find catalogs via GET /v1/ads/catalogs and product sets via GET /v1/ads/catalogs/{catalogId}/product-sets. - &#x60;catalog_sales&#x60; shape: single shape only, no creatives[], dynamicCreative, placementAssets, existingCreativeId or carouselCards. Works with &#x60;existingCampaignId&#x60;, and with &#x60;adSetId&#x60; to add to an existing ad set (then only &#x60;promotedObject.productSetId&#x60; is required). Pick the format with &#x60;catalogFormat&#x60;. - &#x60;traffic&#x60; with &#x60;promotedObject.productSetId&#x60;: a catalog ad without a pixel (OUTCOME_TRAFFIC, &#x60;optimizationGoal&#x60; LINK_CLICKS by default or LANDING_PAGE_VIEWS). The product set goes on the template creative only, never the ad set&#39;s promoted_object. No &#x60;pixelId&#x60; or &#x60;customEventType&#x60; needed. Same creative rules as &#x60;catalog_sales&#x60;. - &#x60;page_likes&#x60;: Page Likes under OUTCOME_ENGAGEMENT (destination_type ON_PAGE, optimization PAGE_LIKES). &#x60;promotedObject.pageId&#x60; is optional and auto-filled. The CTA is fixed to LIKE_PAGE for that Page; headline / body / linkUrl / callToAction / imageUrl / video are all optional (Meta derives them from the Page). - &#x60;page_visits&#x60;: \&quot;Page visits and followers\&quot; under OUTCOME_TRAFFIC (destination_type FACEBOOK_PAGE, optimization PROFILE_VISIT). &#x60;promotedObject.pageId&#x60; is optional and auto-filled; &#x60;linkUrl&#x60; defaults to the Page. Accounts Meta has not enabled are refused with \&quot;This account isn&#39;t eligible to use Profile Visit ads yet\&quot;.  **TikTok**  - &#x60;conversions&#x60;: website-conversion ad group. Requires &#x60;promotedObject.pixelId&#x60; (your TikTok Pixel ID). Optional &#x60;promotedObject.customEventType&#x60;: a TikTok optimization_event code your pixel tracks (newer pixels: e.g. SHOPPING for purchases; legacy: ON_WEB_ORDER, INITIATE_ORDER, ON_WEB_REGISTER, FORM). To inherit pixel and event from an existing ad group, pass &#x60;adSetId&#x60;.  **LinkedIn**  - &#x60;engagement&#x60;, &#x60;traffic&#x60;, &#x60;awareness&#x60;, &#x60;video_views&#x60;: standalone Direct Sponsored Content ads. &#x60;traffic&#x60; requires &#x60;linkUrl&#x60;; &#x60;video_views&#x60; requires &#x60;video&#x60;. - &#x60;lead_generation&#x60;: requires &#x60;leadGenFormId&#x60; (an adForm ID from POST /v1/ads/lead-forms). Sets the campaign objective to MAX_LEAD and the creative&#39;s &#x60;leadgenCallToAction&#x60; destination to &#x60;urn:li:adForm:{id}&#x60;. - &#x60;job_applicants&#x60;: requires a &#x60;platformSpecificData.jobs&#x60; creative. - &#x60;conversions&#x60; or promoting an existing post: use POST /v1/ads/boost.  **OpenAI Ads**  - Only &#x60;traffic&#x60;, &#x60;awareness&#x60;, &#x60;conversions&#x60; (other goals return 400). They map to OpenAI&#39;s &#x60;bidding_type&#x60; (clicks, impressions, conversions). - &#x60;conversions&#x60; needs an active conversion event setting on the account, or returns 400. Create a tracking tag with &#x60;defaultEventType&#x60; (&#x60;POST /v1/accounts/{accountId}/tracking-tags&#x60;) or configure one in OpenAI Ads Manager. - Pick the event with &#x60;promotedObject.customEventType&#x60; (see AdPromotedObject); without it, the most recently created optimizable event is used.  **Reddit Ads**  - Supported: &#x60;traffic&#x60; (CLICKS), &#x60;awareness&#x60; (BRAND_AWARENESS), &#x60;conversions&#x60;, &#x60;video_views&#x60; (VIDEO_VIEWABLE_IMPRESSIONS), &#x60;lead_generation&#x60; (LEAD_GENERATION). Any other goal returns 400. - &#x60;conversions&#x60;: requires &#x60;promotedObject.customEventType&#x60;; the pixel must already have received that event (see AdPromotedObject). - &#x60;lead_generation&#x60;: sends people to &#x60;linkUrl&#x60; and optimizes toward the pixel&#39;s Lead event, which the pixel must already have received. Reddit retired native lead forms on September 30, 2026, so &#x60;leadGenFormId&#x60; returns 400. - &#x60;video_views&#x60;: needs a &#x60;video&#x60; (422 otherwise); &#x60;optimizationGoal&#x60; picks VIDEO_VIEW_6S (default) or VIDEO_VIEW_15S. .</param>
        /// <param name="smartTargeting">smartTargeting.</param>
        /// <param name="optimizationGoal">Explicit optimization goal. Supported on:  - **TikTok** with goal video_views: ENGAGED_VIEW (the 6-second default) or ENGAGED_VIEW_FIFTEEN; both bill per view. - **Reddit** with goal video_views: VIDEO_VIEW_6S (default) or VIDEO_VIEW_15S; other values return 400. - **Meta:** the ad-set &#x60;optimization_goal&#x60; (e.g. &#x60;LANDING_PAGE_VIEWS&#x60;, &#x60;LINK_CLICKS&#x60;, &#x60;REACH&#x60;, &#x60;IMPRESSIONS&#x60;, &#x60;OFFSITE_CONVERSIONS&#x60;, &#x60;THRUPLAY&#x60;, &#x60;LEAD_GENERATION&#x60;).  On Meta it overrides the default derived from &#x60;goal&#x60; (e.g. &#x60;traffic&#x60; defaults to &#x60;LINK_CLICKS&#x60;). It is forwarded verbatim; Meta validates compatibility with the campaign objective and rejects incompatible combinations..</param>
        /// <param name="billingEvent">Meta only. Explicit ad-set &#x60;billing_event&#x60;. Defaults to &#x60;IMPRESSIONS&#x60;. Forwarded verbatim to Meta, which validates compatibility with the optimization goal..</param>
        /// <param name="buyingType">Meta only. Buying type. Defaults to AUCTION and is explicitly sent on new campaigns, including validateOnly. Reusing existingCampaignId does not change the campaign.  RESERVED &#x3D; Reach &amp; Frequency:  - Requires &#x60;rfPredictionId&#x60; (a RESERVED prediction from /v1/ads/rf-predictions + /reserve). - Budget, schedule and pricing come from the reservation, so budgetAmount/budgetType are not required and bid fields are ignored. - Only the plain single-ad shape (no creatives[], adSetId, existingCampaignId or dynamicCreative). (default to BuyingTypeEnum.AUCTION).</param>
        /// <param name="rfPredictionId">Meta only. The RESERVED prediction id the R&amp;F ad set runs on (reserving mints a new id, so pass that one). Requires buyingType RESERVED..</param>
        /// <param name="promotion">Not supported. Meta validates creative_sourcing_spec.promotion_metadata_spec on the create call and then discards it, so a Promotion set through the Marketing API never reaches the creative.  Any object is rejected with 400 invalid_field_value. Send null or omit the field, and set the Promotion on the ad in Ads Manager. Verified on 2026-09-11 across Graph v19.0 to v25.0 and every write path. .</param>
        /// <param name="creativeFeatures">Meta only. Applied to each new creative, including standalone, attach and catalog template shapes.  - With creatives[], these are defaults; an item replaces the whole feature map, including an empty map. - auto_promotion_tag is an Advantage+ enhancement, not the Ads Manager Promotion setting. - On catalog ads, the catalog enhancements are keys of this same map, for example &#x60;{ \&quot;product_extensions\&quot;: \&quot;OPT_OUT\&quot;, \&quot;media_type_automation\&quot;: \&quot;OPT_OUT\&quot;, \&quot;standard_enhancements_catalog\&quot;: \&quot;OPT_OUT\&quot;, \&quot;multi_creative_post_carousel\&quot;: \&quot;OPT_OUT\&quot; }&#x60;. .</param>
        /// <param name="catalogFormat">Meta catalog template creatives only (goal &#x60;catalog_sales&#x60;, goal &#x60;traffic&#x60; with &#x60;promotedObject.productSetId&#x60;, or &#x60;adSetId&#x60; with &#x60;promotedObject.productSetId&#x60;); a 400 otherwise. Omit it to let Meta pick the format.  Sent as &#x60;object_story_spec.template_data.format_option&#x60;. &#x60;force_single_link&#x60; is never sent with it (Meta rejects the pair, subcode 1443051).  - &#x60;single_image&#x60;: also sends &#x60;format_transformation_spec&#x60; with &#x60;carousel&#x60; and &#x60;da_collection&#x60; set to &#x60;data_source: [\&quot;none\&quot;]&#x60;, so Meta keeps the single image instead of turning it into a carousel or collection. - &#x60;carousel_images_single_item&#x60;: also sends &#x60;template_data.multi_share_end_card: false&#x60;, which Meta requires for that format (subcode 1443167). .</param>
        /// <param name="multiAdvertiser">Meta only. Multi-advertiser ads: whether Meta may show this ad alongside other advertisers&#39; in one unit. Meta auto-enrols since Aug 2024, so send OPT_OUT to leave. It is a top-level creative field, NOT a &#x60;creativeFeatures&#x60; key, and Meta rejects it there..</param>
        /// <param name="aiDisclosure">Meta only. Meta&#39;s \&quot;Ad includes media created or edited with AI\&quot; disclosure (the Ads Manager checkbox), stored on the creative as &#x60;generative_asset_spec.transparency_metadata.self_disclosure&#x60;.  - OPT_IN: checks it. - OPT_OUT: explicitly declares no AI media. - Omitted: leaves Meta&#39;s default.  Applied to each new creative (standalone, creatives[] and attach shapes) and preserved when a creative is rebuilt. This sets the disclosure on the ad; whether and when the viewer-facing label renders is Meta&#39;s decision. .</param>
        /// <param name="validateOnly">Validate the request without creating anything. Any other platform, or a Google campaignType other than pmax or demand_gen, returns 501 &#x60;feature_not_available&#x60;.  **Google Performance Max**: validates the complete atomic campaign and asset group, with no resource creation or local persistence. Validation still downloads image URLs and consumes quota.  **Meta**: validates the inline campaign, ad set, creative and ad with execution_options validate_only. Nothing is uploaded or created; validation bypasses Idempotency-Key storage. Success returns 200 with per-node results; a Meta rejection returns an error.  - Supported: a single image or existing video.id (each also with bodies[] / headlines[] Multiple Text Options), all-image placementAssets with per-rule copy and text pools, or existingCreativeId. - Return 400: dynamicCreative, translations, carouselCards, placement videos, new video uploads, creatives[], adSetId, RESERVED buying. - Placement validation uses existing Instagram identities only. Existing campaign or creative nodes are marked skipped. - When Meta cannot dry-run the nested tree, the campaign and creative are validated alone and the adSet and ad nodes return unverified with the reason. This covers code 2, and two errors Meta returns but then creates normally (below). - Code 1 (unknown error) on an OFFSITE_CONVERSIONS ad set nested in a new campaign (some website-conversion ad sets). - Code 100 subcode 2446880 \&quot;WhatsApp number required\&quot; on an ad that does not message on WhatsApp (intermittent). If the creative&#39;s own dry run also asks for a WhatsApp number, the creative is unverified too. Messaging ads still fail on 2446880.  **ChatGPT (OpenAI)**: no platform dry-run. Zernio runs every check it knows (creative lengths, budget, bid strategy, targeting) plus live lookups of the conversion event and target countries, and uploads or creates nothing. OpenAI&#39;s own checks (image fetch, currency-specific minimums, ad review) run only on a real create. .</param>
        /// <param name="budgetAmount">Budget in WHOLE currency units (USD: 50 &#x3D; $50.00), NOT cents. Meta&#39;s own Marketing API takes this number in minor units, an easy and expensive mix-up.  Required on legacy, multi-creative and Performance Max shapes. Inherited on attach.  **OpenAI Ads:** in the ad account currency, minimum 1. OpenAI can require a higher daily minimum for some currencies and names it in the error..</param>
        /// <param name="budgetType">Defaults to daily when &#x60;budgetAmount&#x60; is sent without it (reported in &#x60;appliedDefaults.budgetType&#x60;). Inherited on attach.  - **OpenAI Ads:** accepts both as the campaign&#39;s single spend cap. A lifetime cap can later switch to daily with PUT /v1/ads/campaigns/{campaignId}, but never daily back to lifetime (422). Automatic bidding (Maximize Results) needs a daily budget. - **Reddit Ads:** the ad group&#39;s daily or lifetime spend goal..</param>
        /// <param name="status">Publish state of the created entities, on every platform. Omitted or ACTIVE publishes live (default, back-compat).  PAUSED pauses only the TOP-MOST object this call creates and switches everything below it on, so one resume of that object brings the new tree live and nothing pre-existing is touched:  - New campaign: held paused with its ad set and ad on. - With &#x60;existingCampaignId&#x60;: the new ad set is held paused with its ad on. - With &#x60;adSetId&#x60;: the new ad itself is paused.  **Level overrides.** &#x60;campaignStatus&#x60;, &#x60;adSetStatus&#x60; and &#x60;adStatus&#x60; set one level each and always win for that level. &#x60;status: PAUSED&#x60; adds its own hold only when none of them is PAUSED. &#x60;campaignStatus: ACTIVE&#x60; with &#x60;status: PAUSED&#x60; moves the pause down to the new ad set. To create every object paused, send all three as PAUSED.  **Platform notes:**  - LinkedIn: a held campaign group is PAUSED with its campaign and creative ACTIVE. A new campaign in an existing group stays DRAFT. A held creative (with &#x60;adSetId&#x60;) is created DRAFT, as LinkedIn refuses PAUSED until its review is APPROVED. - X: no per-ad switch, so its lowest level is the line item. - Google Performance Max and Demand Gen: accept PAUSED only (the campaign is created paused). .</param>
        /// <param name="campaignStatus">Every platform. Sets the switch of the new campaign alone (LinkedIn: the campaign group) and overrides &#x60;status&#x60; for it. Omitted, it follows &#x60;status&#x60;. Ignored when the request creates no campaign (&#x60;existingCampaignId&#x60; or &#x60;adSetId&#x60;).  - &#x60;PAUSED&#x60;: holds the campaign off with its ad set and ad on, unless &#x60;adSetStatus&#x60; or &#x60;adStatus&#x60; say otherwise. - &#x60;ACTIVE&#x60; with &#x60;status: PAUSED&#x60;: switches the campaign on and holds the new ad set paused (its ad on). .</param>
        /// <param name="adSetStatus">Every platform. Sets the switch of the new ad set alone and overrides &#x60;status&#x60; for it. When omitted, it follows &#x60;status&#x60;. Equivalent object: Google, TikTok, Pinterest and ChatGPT, the ad group; LinkedIn, the campaign (stays DRAFT when held); X, the line item.  Precedence: a level status (&#x60;campaignStatus&#x60;, &#x60;adSetStatus&#x60;, &#x60;adStatus&#x60;) always wins for its level. &#x60;status: PAUSED&#x60; then holds the top-most new object with no level status, only when no level status is PAUSED. Every other new object is switched on.  So &#x60;campaignStatus: ACTIVE&#x60; + &#x60;adSetStatus: PAUSED&#x60; + &#x60;adStatus: PAUSED&#x60; keeps the campaign on with the new ad set and ad off; all three PAUSED creates the whole tree paused.  Rejected with a 400 alongside &#x60;adSetId&#x60; (that ad set exists; change it with PUT /v1/ads/ad-sets/{adSetId}/status). Performance Max and Demand Gen accept PAUSED only. .</param>
        /// <param name="adStatus">Sets the switch of the new ad alone, also when attaching to an existing ad set with &#x60;adSetId&#x60;, and overrides &#x60;status&#x60; for it. Same precedence as &#x60;adSetStatus&#x60;. Omitted, it follows &#x60;status&#x60;.  - LinkedIn: a creative held off is created DRAFT, because LinkedIn refuses PAUSED on a creative until its review is APPROVED. A DRAFT creative is not submitted for review and cannot serve; it reads &#x60;paused&#x60;. Resuming the ad (PUT /v1/ads/{adId}/status &#x60;active&#x60;) switches it ACTIVE, which starts the review. - X: returns a 400. A promoted post has no switch of its own, so hold the line item with &#x60;adSetStatus&#x60;. - &#x60;PAUSED&#x60; with &#x60;buyingType: RESERVED&#x60;: returns a 400 (Meta creates the first Reach and Frequency ad ACTIVE). - Performance Max and Demand Gen: accept PAUSED only. .</param>
        /// <param name="budgetLevel">Meta only. Where the budget lives, which selects the Meta budget model:  - &#x60;adset&#x60; (default): ABO (Ad-set Budget Optimization). The budget is set on the ad set. Back-compatible; omit this field to keep it. - &#x60;campaign&#x60;: CBO (Campaign Budget Optimization / Advantage Campaign Budget). The budget AND &#x60;bidStrategy&#x60; are set on the CAMPAIGN, and Meta distributes spend across ad sets automatically.  The returned ad stores the applied &#x60;budgetLevel&#x60;, and the budget in &#x60;campaignBudget&#x60; (CBO) or &#x60;adSetBudget&#x60; (ABO). Edit CBO budgets with &#x60;PUT /v1/ads/campaigns/{campaignId}&#x60; and ABO budgets with &#x60;PUT /v1/ads/ad-sets/{adSetId}&#x60;.  Meta requires the budget at exactly one level, never both. Non-Meta platforms ignore this field. Ignored on the attach shape (&#x60;adSetId&#x60;), which inherits the existing budget.  (default to BudgetLevelEnum.Adset).</param>
        /// <param name="currency">ISO 4217 currency code matching the ad account&#39;s currency (e.g. &#x60;USD&#x60;). Meta only. Optional: Zernio resolves it from the ad account when omitted. The value selects the minor-unit exponent Zernio converts budget/bid amounts by before calling Meta (most currencies are cents; zero-decimal currencies like JPY/KRW are sent as-is)..</param>
        /// <param name="headline">Ad headline. Required for Meta, Google, Pinterest, LinkedIn, OpenAI Ads and Reddit Ads on legacy + attach shapes (for multi-creative, skip it and use &#x60;creatives[].headline&#x60;). Ignored for TikTok.  Max length: Meta&#x3D;255, Google&#x3D;30, Pinterest&#x3D;100, LinkedIn&#x3D;400, OpenAI&#x3D;50 (min 3), Reddit&#x3D;300.  - LinkedIn: the ad&#39;s headline (the bold text on the creative); for traffic ads, the link card title. - OpenAI Ads: the chat card&#39;s title. - Reddit: the promoted post&#39;s title. - X: the website card title (needs imageUrl and linkUrl, max 70)..</param>
        /// <param name="longHeadline">Google Display only. Defaults to &#x60;headline&#x60; if omitted. On LinkedIn, reused as the optional secondary description text on traffic (link) ads; omitted if not provided..</param>
        /// <param name="body">Required on legacy + attach shapes.  - X: the tweet text (max 280 chars including a ~24-char URL when &#x60;linkUrl&#x60; is set). - LinkedIn: the post commentary (the intro text shown above the ad). - OpenAI Ads: the chat card&#39;s body text. - Reddit: the promoted post&#39;s body. Optional on image, video and carousel ads, required on text ads.  Max: Google&#x3D;90, Pinterest&#x3D;500, OpenAI&#x3D;100..</param>
        /// <param name="description">Meta only (facebook/instagram). Link description: the secondary text shown below the headline (Meta&#39;s link_data.description; on video creatives mapped to video_data.link_description). When omitted, Meta auto-pulls the destination URL&#39;s OpenGraph description.  - Applies on legacy, attach, and placementAssets shapes. - For multi-creative use creatives[].description (this field is the shared fallback). - For multi-text variations use &#x60;descriptions&#x60; (array) instead..</param>
        /// <param name="bodies">Meta only. Multiple Text Options (Advantage+ Flexible Format): 1-5 primary-text variations that Meta optimises delivery across, WITHOUT enabling full Dynamic Creative (&#x60;dynamicCreative&#x60;).  Uses &#x60;optimization_type: DEGREES_OF_FREEDOM&#x60; on the asset feed, so multiple ads per ad set are allowed (unlike &#x60;dynamicCreative&#x60;, which is limited to one).  **Requirements:** &#x60;imageUrl&#x60; or &#x60;video&#x60;, &#x60;linkUrl&#x60;, &#x60;callToAction&#x60;, and &#x60;headlines&#x60;. The top-level &#x60;body&#x60; becomes &#x60;object_story_spec.link_data.message&#x60; (the preview text). On a video creative the copy lands in &#x60;video_data.message&#x60; / &#x60;video_data.title&#x60; instead of &#x60;link_data&#x60;.  Mutually exclusive with &#x60;dynamicCreative&#x60;, &#x60;carouselCards&#x60;, and &#x60;creatives[]&#x60;.  **With &#x60;placementAssets&#x60;:** the pool applies to the placement-customized creative instead (&#x60;optimization_type: PLACEMENT&#x60;). Every body carries the label of each rule that does not pin its own &#x60;body&#x60; (same for &#x60;headlines&#x60;), so Meta rotates options per placement while media stays pinned.  A rule&#39;s own &#x60;body&#x60; / &#x60;headline&#x60; stays pinned for that placement. &#x60;descriptions[]&#x60; cannot join a placement-customized creative (Meta refuses a second description per rule, subcode 1885878). .</param>
        /// <param name="headlines">Meta only. Headline variations for Multiple Text Options. Must be sent alongside &#x60;bodies&#x60;. The top-level &#x60;headline&#x60; field is used as the &#x60;object_story_spec.link_data.name&#x60; (&#x60;video_data.title&#x60; on a video creative). .</param>
        /// <param name="descriptions">Meta only. Optional description variations for Multiple Text Options. Sent alongside &#x60;bodies&#x60; and &#x60;headlines&#x60;..</param>
        /// <param name="callToAction">The ad&#39;s call-to-action button.  - **Meta:** required on legacy + attach shapes. Accepts every call to action type Meta itself accepts (the enum lists them), including values such as SEE_DETAILS that ads synced from Meta carry. - **TikTok:** honoured, passed through to the Spark Ad creative&#39;s &#x60;call_to_action&#x60;. - **LinkedIn:** the CTA button on the ad; defaults to LEARN_MORE when &#x60;linkUrl&#x60; is set. Accepts LEARN_MORE, SIGN_UP, DOWNLOAD, SUBSCRIBE, REGISTER, JOIN, ATTEND, REQUEST_DEMO, VIEW_QUOTE, APPLY, SEE_MORE, SHOP_NOW, BUY_NOW. - **Reddit** (image, video and carousel ads): accepts LEARN_MORE, SHOP_NOW, SIGN_UP, CONTACT_US, DOWNLOAD, GET_QUOTE, SUBSCRIBE, APPLY_NOW, BOOK_NOW, BUY_TICKETS, DONATE_NOW, GET_DIRECTIONS, GET_SHOWTIMES, LISTEN_NOW, ORDER_NOW, SEE_MENU, INSTALL_MOBILE_APP. Other values return 400. - **Google, Pinterest, and X:** ignored..</param>
        /// <param name="linkUrl">The ad&#39;s destination URL. Required on legacy + attach shapes (skip for multi-creative). NOT required when &#x60;goal&#x60; is &#x60;lead_generation&#x60; (the ad opens a Lead Gen form instead).  - **LinkedIn:** required for &#x60;traffic&#x60; ads, optional for &#x60;engagement&#x60; / &#x60;awareness&#x60;. &#x60;imageUrl&#x60; + &#x60;linkUrl&#x60; publishes an ARTICLE-content creative (LinkedIn&#39;s article ad format), with the image as thumbnail and &#x60;longHeadline&#x60; as description. - **OpenAI Ads:** required (the chat card&#39;s target_url). - **Reddit:** required on image and video ads (the post&#39;s destination and the ad&#39;s click URL), the fallback for carousel cards without their own, and refused with 400 on text ads..</param>
        /// <param name="leadGenFormId">Lead Gen form ID to attach to the ad&#39;s creative. REQUIRED when &#x60;goal&#x60; is &#x60;lead_generation&#x60;. Create one via POST /v1/ads/lead-forms.  - Meta (facebook/instagram): the leadgen_forms ID. The ad set&#39;s promoted_object.page_id, LEAD_GENERATION optimization and destination_type ON_AD are derived automatically from the goal. - Meta: also required on every ATTACH (&#x60;adSetId&#x60;) call targeting a lead ad set (the form attaches per-ad; Meta rejects a formless ad in a lead ad set). - Meta: &#x60;placementAssets&#x60;, &#x60;dynamicCreative&#x60; and &#x60;carouselCards&#x60; (multi-card Instant-Form lead ad) ARE supported on instant-form lead ads. &#x60;linkUrl&#x60; and per-card &#x60;linkUrl&#x60; are optional, forwarded as real destinations when sent, else falling back to Meta&#39;s lead-form link. - LinkedIn: the adForm ID. The creative&#39;s &#x60;leadgenCallToAction.destination&#x60; is set to &#x60;urn:li:adForm:{id}&#x60; and the campaign objective to MAX_LEAD. Forms must be owned by the sponsoredAccount (not the organization) for the URN to resolve. - Reddit: rejected with 400 on every goal (Reddit retired its native lead forms)..</param>
        /// <param name="imageUrl">Image creative for Meta/Google/Pinterest/LinkedIn on legacy + attach shapes. Mutually exclusive with &#x60;video&#x60;.  - LinkedIn: required unless &#x60;video&#x60; is set. Uploaded to LinkedIn under the authoring Company Page (see &#x60;organizationId&#x60;); recommended ratio 1.91:1 (e.g. 1200×627). - Google: not required for Search campaigns. For Display, treated as the landscape image (alias of &#x60;images.landscape&#x60;); supply &#x60;images.square&#x60; alongside or the request is rejected. - TikTok: this field carries the VIDEO URL (the TikTok ads endpoint is video-only; the &#x60;imageUrl&#x60; name is kept for cross-platform consistency). - X: imageUrl + headline + linkUrl together build a website card (image, title and destination under the post; the URL is not added to the post text). Sending only some of them is a 400. - X: description, video and callToAction are rejected with 400 (promote a post that carries a video with POST /v1/ads/boost). - OpenAI Ads: required, uploaded as the chat card&#39;s image (OpenAI has no video ad format). - Reddit: builds an image ad (requires &#x60;linkUrl&#x60;). On a Reddit video ad it is the fallback for &#x60;video.thumbnailUrl&#x60;..</param>
        /// <param name="images">images.</param>
        /// <param name="video">video.</param>
        /// <param name="creatives">Meta-only. When present, switches to the multi-creative shape: creates 1 campaign + 1 ad set + N ads (one per entry here). Top-level &#x60;headline&#x60; / &#x60;body&#x60; / &#x60;imageUrl&#x60; / &#x60;linkUrl&#x60; / &#x60;callToAction&#x60; are ignored in this mode. Mutually exclusive with &#x60;adSetId&#x60;. .</param>
        /// <param name="adSetId">When present, switches to the attach shape: adds one new ad to this existing ad set without creating a new campaign. Mutually exclusive with &#x60;creatives[]&#x60;.  **Inherited from the ad set on Meta:** budget, targeting, goal, schedule and bid strategy. Passing &#x60;bidStrategy&#x60; in attach mode returns 400 (change an ad set&#39;s bid with &#x60;PUT /v1/ads/ad-sets/{adSetId}&#x60;). &#x60;dynamicCreative&#x60; returns 400 in attach mode: omit &#x60;adSetId&#x60; to create a new dynamic ad set instead.  **Creative.** The attached ad takes the full single-creative surface: &#x60;headline&#x60;/&#x60;body&#x60;/&#x60;description&#x60;/&#x60;callToAction&#x60; plus one of:  - &#x60;imageUrl&#x60;/&#x60;video&#x60; - &#x60;placementAssets&#x60; (its own per-placement Feed/Story assets) - &#x60;translations&#x60;/&#x60;defaultLocale&#x60; (its own per-locale asset feed, Meta only)  Pass &#x60;leadGenFormId&#x60; on EVERY ad attached to a lead ad set: the parent must be ON_AD (true for ad sets created via goal &#x60;lead_generation&#x60;), and Meta rejects a formless ad there.  To build N full ads sharing one ad set, create the first ad via the normal shape, then attach the rest one call each.  **Platforms.** Supported on Meta (facebook, instagram), Google Ads, TikTok, LinkedIn and Reddit Ads.  - TikTok: &#x60;adSetId&#x60; is the ad group ID; the new ad inherits the ad group&#39;s bid, budget and targeting. - LinkedIn: &#x60;adSetId&#x60; is the LinkedIn Campaign ID (numeric). We attach a new Creative to that Campaign, so its &#x60;platformSpecificData&#x60; bidding, targeting, budget and schedule are inherited (passing those fields returns 400). - Reddit Ads: &#x60;adSetId&#x60; is the AD GROUP id. Only the post and the ad are created; the ad group keeps its budget, schedule, targeting, bid and optimization. &#x60;goal&#x60; is not required. An ad group of another ad account returns 404. - Reddit Ads, rejected with 400: &#x60;budgetAmount&#x60;, &#x60;budgetType&#x60;, &#x60;startDate&#x60;, &#x60;endDate&#x60;, targeting fields, &#x60;promotedObject&#x60;, &#x60;tracking.pixelId&#x60; and &#x60;optimizationGoal&#x60;.  **Google Ads.** &#x60;adSetId&#x60; is the AD GROUP id (numeric). &#x60;goal&#x60; is not required: the ad group keeps its campaign&#39;s bidding, budget and targeting. &#x60;validateOnly&#x60; is supported.  - &#x60;campaignType&#x60; is read from the ad group&#39;s campaign (Search, Display or Demand Gen) and can be omitted. A contradicting &#x60;campaignType&#x60; returns 400, an ad group Google does not know in that customer returns 404, and any other campaign type returns 422. - A Search ad needs &#x60;headline&#x60; + &#x60;body&#x60; + &#x60;linkUrl&#x60;; a Display ad also needs &#x60;images.landscape&#x60; + &#x60;images.square&#x60; + &#x60;businessName&#x60;. - Google allows 3 responsive search ads per ad group: a fourth returns 422 naming the limit (&#x60;RESPONSIVE_SEARCH_ADS_PER_AD_GROUP&#x60;) and the ad group. - &#x60;budgetAmount&#x60;/&#x60;budgetType&#x60; and bidding fields (&#x60;bidStrategy&#x60;, &#x60;bidAmount&#x60;, &#x60;portfolioBidStrategyId&#x60;) return 400; the ad group already owns them. - With &#x60;campaignType: \&quot;demand_gen\&quot;&#x60; the ad group must belong to a Demand Gen campaign (otherwise 400). &#x60;demandGen&#x60; carries only the ad&#39;s creative, and the new ad is created PAUSED. - Demand Gen ad group settings return 400: geo, languages, &#x60;demandGen.channels&#x60;/&#x60;audience&#x60;/&#x60;audienceId&#x60;/ &#x60;adGroupName&#x60;. .</param>
        /// <param name="existingCampaignId">Create the new objects under this EXISTING campaign instead of creating a new one. Supported on Meta, Google Ads, LinkedIn, TikTok and Reddit Ads. Mutually exclusive with &#x60;adSetId&#x60; and &#x60;creatives[]&#x60;.  - TikTok: creates the ad group and the ad under this campaign. The campaign is neither created nor activated, and its objective must fit &#x60;goal&#x60;. Not with &#x60;smartPlus&#x60;. - Meta: adds the new ad set under this campaign (multi-ad-set audience testing). Its budget matches the campaign&#39;s mode: for a CBO campaign (campaign-level budget) omit &#x60;budgetAmount&#x60;/&#x60;budgetType&#x60;, since the campaign owns the budget; for an ABO campaign pass them (they go on the new ad set). - LinkedIn: creates a new Campaign (and its Creative) under this EXISTING CampaignGroup. - Google Ads: creates a new ad group under this campaign. It inherits the campaign&#39;s budget, so omit &#x60;budgetAmount&#x60;/&#x60;budgetType&#x60; (and any bidding field), or the request returns 400. - Google Ads with &#x60;campaignType: \&quot;demand_gen\&quot;&#x60;: the campaign must be Demand Gen (otherwise 400). The new ad group (with its geo, languages, channels and audience from the request) and its ad are created in one atomic request, the ad group PAUSED. Schedule and &#x60;locationTargetingType&#x60; belong to the campaign and return 400. - Google Ads, campaign migrated from Discovery that still targets locations and languages on the campaign: geo and language fields return 400 on a new ad group, which follows the campaign&#39;s targeting. - Google Ads failure: only the entities we authored are cleaned up. The pre-existing parent is left untouched and is never (re)activated. - Reddit Ads: creates a new ad group and the ad under this campaign. &#x60;goal&#x60; may be omitted (the campaign&#39;s objective decides it); any other goal returns 400 naming the one to send. If the ad fails, the new ad group is archived. - Reddit Ads dates: the ad group must start no earlier than a future campaign start and end no later than the campaign end (400 otherwise). Without &#x60;endDate&#x60; it ends with the campaign. - Reddit Ads, campaign without a campaign budget: send &#x60;budgetAmount&#x60;/&#x60;budgetType&#x60; for the new ad group (400 without them). Bid, conversion event and pixel work as on a new campaign. - Reddit Ads under campaign budget optimization: the ad group takes the campaign&#39;s bid, goal type, optimization event and pixel and has no budget of its own. &#x60;budgetAmount&#x60;/&#x60;budgetType&#x60;, bid fields, or another conversion event or pixel return 400, as does an &#x60;endDate&#x60; when the campaign has no end date. - Reddit Ads errors: a campaign of another ad account returns 404, a Reddit Max campaign 422. .</param>
        /// <param name="phoneNumber">Meta attach shape only (&#x60;adSetId&#x60;). The phone number (E.164, e.g. &#x60;+4712345678&#x60;) for an ad added to a \&quot;website and phone call\&quot; ad set (destination_type &#x60;WEBSITE_AND_PHONE_CALL&#x60;), sent as the creative&#39;s call configuration.  Optional: when omitted, the number on the ad set&#39;s existing ads is reused; if none carries one, the request is a 400.  Rejected with 400 on any other ad set, with &#x60;existingCreativeId&#x60;, without &#x60;adSetId&#x60;, or on other platforms (a new call campaign is &#x60;POST /v1/ads/call&#x60;). .</param>
        /// <param name="existingCreativeId">Meta only. Reuse an EXISTING ad creative by id instead of building a new one from the copy/media fields (which are then ignored).  - Combine with &#x60;existingCampaignId&#x60; to build a multi-ad-set campaign that shares one creative. - Mutually exclusive with &#x60;creatives[]&#x60;, &#x60;dynamicCreative&#x60;, and &#x60;placementAssets&#x60;. - The creative id used is returned as &#x60;creativeId&#x60; on the create response. .</param>
        /// <param name="businessName">Google Display only.</param>
        /// <param name="boardId">Pinterest only. Board ID (auto-creates if not provided)..</param>
        /// <param name="organizationId">LinkedIn only (ignored by every other platform). The Company Page that authors the Direct Sponsored Content (\&quot;dark\&quot;) post backing the ad. Accepts a numeric organization ID or a full &#x60;urn:li:organization:N&#x60; URN.  Required unless it defaults:  - to the page, when the resolved &#x60;accountId&#x60; is a connected LinkedIn Company-Page account; - to the owning organization, when the LinkedIn ad account is org-owned.  The authenticated member must be an ADMINISTRATOR or DIRECT_SPONSORED_CONTENT_POSTER of this page, and the page must be associated with the ad account, or LinkedIn returns 403..</param>
        /// <param name="targeting">Nested targeting object: the same TargetingSpec shape as &#x60;POST /v1/ads/boost&#x60;, &#x60;POST /v1/ads/targeting/reach-estimate&#x60;, and &#x60;saved_targeting&#x60; audiences.  Merged UNDER the flat inline targeting fields below: &#x60;savedTargetingId&#x60; &lt; &#x60;targeting&#x60; &lt; flat fields (a flat field present on the body replaces the nested value entirely). Both forms are equivalent; use whichever your integration already builds.  Reddit-only targeting (&#x60;communities&#x60;, &#x60;excludedCommunities&#x60;, &#x60;conversationKeywords&#x60;, &#x60;excludedConversationKeywords&#x60;) is sent here. .</param>
        /// <param name="countries">ISO 3166-1 alpha-2 country codes (e.g. [&#39;NL&#39;]). Defaults to [&#39;US&#39;] when no other geo targeting (flat or nested &#x60;targeting&#x60;) is provided. (LinkedIn and OpenAI Ads currently honour country-level targeting only; any other targeting field returns 400 for OpenAI Ads.).</param>
        /// <param name="countryGroups">Meta only. Continents and trade blocs (&#x60;geo_locations.country_groups&#x60;), for targeting a whole region without listing its countries. Combines with &#x60;countries&#x60; rather than replacing it. Discoverable via &#x60;GET /v1/ads/targeting/search?dimension&#x3D;geo&amp;geoType&#x3D;country_group&#x60;. .</param>
        /// <param name="cities">City-level geo targeting (Meta, Google and TikTok). An entry is &#x60;{ key }&#x60; or the key alone as a plain string (&#x60;[\&quot;1006410\&quot;]&#x60;).  Each city is targeted by the platform&#39;s opaque &#x60;key&#x60; (the city ID), found via &#x60;GET /v1/ads/targeting/search?dimension&#x3D;geo&amp;q&#x3D;&lt;name&gt;&amp;countryCode&#x3D;&lt;ISO&gt;&#x60;.  **Radius (Meta only):** optional &#x60;radius&#x60; + &#x60;distance_unit&#x60; extend targeting beyond city limits (e.g. radius 25 km around the center). Set both or omit both (Meta defaults to ~16 km).  - **Meta:** cannot overlap with the same country in &#x60;countries&#x60; (Meta returns a \&quot;locations overlap\&quot; error). Drop the country or scope it to a different one. - **TikTok:** keys are numeric location ids and can be sent without &#x60;countries&#x60;. .</param>
        /// <param name="regions">Region-level (state/province) geo targeting (Meta, Google and TikTok). Each region is targeted by the platform&#39;s opaque &#x60;key&#x60; (the region ID) which can be looked up via &#x60;GET /v1/ads/targeting/search?dimension&#x3D;geo&amp;q&#x3D;&lt;name&gt;&amp;countryCode&#x3D;&lt;ISO&gt;&#x60;. An entry may also be the key alone as a plain string. .</param>
        /// <param name="ageMin">ageMin.</param>
        /// <param name="ageMax">ageMax.</param>
        /// <param name="interests">Interest objects from /v1/ads/targeting/search?dimension&#x3D;interest (or dimension&#x3D;interestKeyword on TikTok). Each must include id and name.  **TikTok:**  - Bare numeric ids are interest categories (&#x60;interest_category_ids&#x60;). - Ids like &#x60;keyword:123456&#x60; from &#x60;dimension&#x3D;interestKeyword&#x60; are additional interests (&#x60;interest_keyword_ids&#x60;). - Any other id returns 422 naming &#x60;targeting.interests&#x60;. - TikTok matches people who fit ANY selected interest, additional interest or behavior (one OR&#39;d group). That group is ANDed with location, age, gender and the other dimensions. .</param>
        /// <param name="zips">Postal/ZIP geo targeting. &#x60;key&#x60; is the platform&#39;s postal location ID from /v1/ads/targeting/search?dimension&#x3D;geo&amp;geoType&#x3D;zip. Supported on Meta, Google, TikTok, Pinterest, X..</param>
        /// <param name="metros">DMA / metro-area geo targeting (Meta and TikTok). &#x60;key&#x60; is the platform&#39;s metro ID from /v1/ads/targeting/search?dimension&#x3D;geo&amp;geoType&#x3D;metro (TikTok metros appear as type &#x60;metro&#x60;, e.g. the New York DMA)..</param>
        /// <param name="customLocations">Point-radius (lat/lng) geo targeting. Meta only (custom_locations). Rejected on platforms without radius support..</param>
        /// <param name="behaviors">Behaviour entities from /v1/ads/targeting/search?dimension&#x3D;behavior (Meta, TikTok and LinkedIn). Each must include id.  **On TikTok:**  - Targets people who interacted with videos (watched to the end, liked, commented or shared, last 15 days) or creators (followed or viewed the profile) in the picked categories. - Or people who viewed videos with a picked hashtag: &#x60;hashtag:&lt;id&gt;&#x60; ids from &#x60;dimension&#x3D;hashtag&#x60;, sent as a &#x60;HASHTAG_RELATED&#x60; action with &#x60;VIEW_HASHTAG&#x60;. - The ad group uses the TikTok placement only. - Behaviors are OR&#39;d with interests and additional interests. .</param>
        /// <param name="workPositions">Meta only. Job title entities from /v1/ads/targeting/search?dimension&#x3D;workPosition. Each must include id. Rejected on other platforms (use LinkedIn&#39;s &#x60;jobTitles&#x60; there)..</param>
        /// <param name="workEmployers">Meta only. Employer entities from /v1/ads/targeting/search?dimension&#x3D;workEmployer. Each must include id..</param>
        /// <param name="workIndustries">Meta only. Work-industry entities from /v1/ads/targeting/search?dimension&#x3D;workIndustry. Each must include id. Rejected on other platforms (use LinkedIn&#39;s &#x60;industries&#x60; there)..</param>
        /// <param name="incomeTier">Normalized household-income tier. Meta and TikTok express all four; Google maps only &#x60;top_10&#x60;; rejected on LinkedIn, X, and Pinterest. On Meta, income targeting is incompatible with housing/employment/credit &#x60;specialAdCategories&#x60;. .</param>
        /// <param name="languages">Language codes, e.g. [\&quot;en\&quot;,\&quot;es\&quot;].  - Google: campaign language targeting (language_constant) using Google&#39;s language codes (ISO 639-1, plus variants such as &#x60;zh_CN&#x60;). Unknown codes return 400. - Meta: a bare code targets all regional variants (\&quot;en\&quot; &#x3D; all English); use a region-qualified code for a specific one (\&quot;en_GB\&quot;, \&quot;pt_BR\&quot;, \&quot;zh_TW\&quot;). Unknown codes are rejected. - Other ad platforms use their own language-code systems..</param>
        /// <param name="placements">placements.</param>
        /// <param name="savedTargetingId">ID of a &#x60;saved_targeting&#x60; audience (created via POST /v1/ads/audiences). When set, its stored TargetingSpec is expanded as the base targeting; inline fields on this body merge on top. Lets you reuse a named targeting preset without re-sending every field. .</param>
        /// <param name="rawTargeting">Meta only. A raw Meta-native targeting spec (snake_case: &#x60;geo_locations&#x60;, &#x60;age_min&#x60;, &#x60;excluded_custom_audiences&#x60;, &#x60;flexible_spec&#x60;, &#x60;targeting_automation&#x60;, &#x60;user_os&#x60;, &#x60;wireless_carrier&#x60;, business places, etc.), the exact shape &#x60;GET /v1/ads/{adId}&#x60; returns for external ads.  Sent alone, it reaches the ad set VERBATIM (the path for cloning a campaign&#39;s targeting exactly). Meta validates it and surfaces any errors.  **Combining with camelCase fields** (countries/regions/cities/interests/ageMin/..., &#x60;targeting&#x60;, &#x60;savedTargetingId&#x60;, &#x60;audienceId&#x60;): rawTargeting is the BASE layer and the built camelCase spec is merged on top, key by key, with camelCase winning on collision.  The camelCase precedence chain stays &#x60;savedTargetingId&#x60; &lt; &#x60;targeting&#x60; &lt; flat fields. Merge rules:  - Inside &#x60;geo_locations&#x60; and &#x60;excluded_geo_locations&#x60; the merge goes one level deep: built sub-keys win, and raw-only sub-keys such as &#x60;location_types&#x60; survive alongside built &#x60;countries&#x60;. - Array values (&#x60;flexible_spec&#x60;, ...) are replaced as a WHOLE key when the camelCase spec builds them, never element-merged. - With rawTargeting present, the defaults the camelCase builder normally injects (US geo, &#x60;targeting_automation.advantage_audience: 0&#x60;) are suppressed, so raw values are not clobbered.  Include &#x60;targeting_automation&#x60; in the raw spec (or send &#x60;advantageAudience&#x60;), as Meta requires it on create. When cloning an EU campaign, also pass &#x60;dsaBeneficiary&#x60; / &#x60;dsaPayor&#x60; (separate fields, not part of targeting). .</param>
        /// <param name="specialAdCategories">Meta only. Declares the ad&#39;s special category, required for housing, employment, credit, or political/social-issue ads (Meta enforces restricted targeting for these). Note: setting a special category disables income/zip targeting on Meta. .</param>
        /// <param name="specialAdCategoryCountry">Meta (metaads) only. 2-letter ISO country codes the special ad category applies to. Requires specialAdCategories to be set (400 otherwise). Ignored when joining an existing campaign via existingCampaignId (the existing campaign&#39;s category/country already governs it). .</param>
        /// <param name="regionalRegulatedCategories">Meta only. Regional regulation categories required when the ad set targets certain countries. Known values: AUSTRALIA_FINSERV, AUSTRALIA_UNIVERSAL, BRAZIL_REGULATION, INDIA_FINSERV, MALAYSIA_UNIVERSAL, SINGAPORE_UNIVERSAL, TAIWAN_FINSERV, TAIWAN_UNIVERSAL, THAILAND_UNIVERSAL. Meta rejects the ad set without this when the targeting geo includes the corresponding country. .</param>
        /// <param name="regionalRegulationIdentities">Meta only. Verified identity IDs of the beneficiary and payer for each declared regionalRegulatedCategories value. Ignored when adSetId adds the ad to an existing ad set.  Meta may require them on ad sets created through the API even when a default beneficiary and payer are set in Ads Manager advertising settings (seen on AUSTRALIA_FINSERV), so sending them explicitly is the reliable path.  **Value**: the Verified identity ID (Meta Business Settings &gt; Verified identities), not a Page or Business ID. Beneficiary and payer may be the same ID. The IDs reach Meta unchanged.  Send each ID as a string of digits: Verified identity IDs can have 17 digits, more than a JSON number holds exactly, and a number that arrives rounded is rejected. Numbers up to 9007199254740991 are still accepted.  **Keys by category**:  - AUSTRALIA_FINSERV: australia_finserv_beneficiary / australia_finserv_payer - TAIWAN_FINSERV: taiwan_finserv_beneficiary / taiwan_finserv_payer - INDIA_FINSERV: india_finserv_beneficiary / india_finserv_payer - TAIWAN_UNIVERSAL: taiwan_universal_beneficiary / taiwan_universal_payer - SINGAPORE_UNIVERSAL: singapore_universal_beneficiary / singapore_universal_payer - AUSTRALIA_UNIVERSAL, BRAZIL_REGULATION, MALAYSIA_UNIVERSAL and THAILAND_UNIVERSAL: universal_beneficiary / universal_payer  **Errors**: when Meta rejects the ad set for a missing verified advertiser, the error carries param regionalRegulationIdentities, details.expectedIdentityKeys (the keys the declared categories expect), details.suggestedCategories (the markets Meta ties to that subcode) and Meta&#39;s metaCode, metaSubcode and fbtraceId. .</param>
        /// <param name="endDate">When the ad ends. If omitted: on a lifetime budget, the ad ends 7 days after it starts (reported in &#x60;appliedDefaults.endDate&#x60;); a daily budget runs until paused.  Read like &#x60;startDate&#x60;: account timezone on Meta, TikTok, X, Pinterest, OpenAI and Reddit; whole account-local days on Google; UTC on LinkedIn. A date-only end runs to 23:59:59 local..</param>
        /// <param name="startDate">Ad-set start time (ISO 8601, e.g. \&quot;2026-06-10T09:00:00Z\&quot;). When omitted the ad starts delivering immediately. Same field as on &#x60;POST /v1/ads/boost&#x60;.  Maps to the ad set&#39;s start: Meta &#x60;start_time&#x60;, TikTok ad group &#x60;schedule_start_time&#x60;, LinkedIn / Pinterest / X / Google campaign start. For lifetime budgets Meta also requires &#x60;endDate&#x60;.  **Values without an offset** (&#x60;YYYY-MM-DD&#x60;, &#x60;YYYY-MM-DD HH:MM:SS&#x60; or &#x60;YYYY-MM-DDTHH:MM:SS&#x60;):  - Meta, TikTok, X, Pinterest, OpenAI and Reddit: read in the ad account timezone (Meta itself would read it as UTC). - Google: runs whole days in the customer account timezone and takes the value&#39;s calendar date as written. - LinkedIn: ad accounts carry no timezone, so it is read as UTC.  The created ad&#39;s &#x60;schedule&#x60; echoes the start and end the platform stored, as UTC instants. When attaching to an existing ad set (&#x60;adSetId&#x60;) it is that ad set&#39;s start and end. .</param>
        /// <param name="pageId">Meta only. The Facebook Page the ad runs as (&#x60;object_story_spec.page_id&#x60;). Defaults to the Page bound to the connection.  Pass another Page ID to run the ad as that Page. Any Page granted to the connection is accepted (for a business-login connection, every Page granted in Meta&#39;s dialog; list them with GET /v1/ads/instagram-accounts).  - The Instagram identity is re-resolved for that Page unless &#x60;instagramAccountId&#x60; is set. - A Page the connection cannot see is a 400 on &#x60;pageId&#x60; naming the granted Pages. .</param>
        /// <param name="instagramAccountId">Meta only. Overrides the Instagram account the ad is delivered as. Pass an Instagram Business Account ID (e.g. 17841...), mapped to the creative&#39;s &#x60;instagram_user_id&#x60;; it is sent as-is and never replaced. Useful when a Page has more than one eligible IG account.  When omitted, we use the Instagram account linked to the Page. Formats that need an Instagram actor without one use the actor the Page&#39;s other ads already run as, then the Page&#39;s page-backed Instagram account.  If Meta refuses that default because the ad account has no access to it (200/1815199), the creative is retried once with an Instagram account the ad account is authorized for. With none, the request fails with a 422 on &#x60;instagramAccountId&#x60; (list the usable accounts with GET /v1/ads/instagram-accounts).  A creative replaced later through /v1/ads/{adId} follows the same rule. .</param>
        /// <param name="dynamicCreative">dynamicCreative.</param>
        /// <param name="carouselCards">Carousel cards. Behavior per platform:  **Reddit:** builds a carousel ad. Each card has its image, destination (card &#x60;linkUrl&#x60;, falling back to top-level &#x60;linkUrl&#x60;; 400 when neither is set), call to action (card &#x60;callToAction&#x60;, falling back to the top-level one) and caption (card &#x60;headline&#x60;, else &#x60;description&#x60;). &#x60;headline&#x60; is still required.  **Meta only:** a hand-built carousel of 2-10 authored cards, sent in order as the creative&#39;s &#x60;link_data.child_attachments&#x60;. Unlike &#x60;dynamicCreative&#x60;, you author every card&#39;s copy and link.  - Meta may still reorder cards for performance (&#x60;multi_share_optimized&#x60; defaults to true); send &#x60;optimizeCardOrder: false&#x60; to keep your order. - Requires top-level &#x60;body&#x60; and &#x60;callToAction&#x60;; &#x60;linkUrl&#x60; too UNLESS &#x60;leadGenFormId&#x60; is set. These become the ad&#39;s Destination and button (&#x60;link_data.link&#x60; / &#x60;link_data.call_to_action&#x60;) and the per-card fallback. - Mutually exclusive with &#x60;imageUrl&#x60;/&#x60;video&#x60;, &#x60;creatives[]&#x60;, &#x60;dynamicCreative&#x60;, &#x60;placementAssets&#x60;, &#x60;existingCreativeId&#x60;, &#x60;adSetId&#x60; and goal &#x60;catalog_sales&#x60;. - With &#x60;leadGenFormId&#x60; it builds a carousel Instant-Form lead ad: &#x60;linkUrl&#x60; and per-card &#x60;linkUrl&#x60; become OPTIONAL, forwarded as real destinations when sent; when omitted, the destination falls back to Meta&#39;s lead-form link. .</param>
        /// <param name="optimizeCardOrder">Meta only (a 400 on any other platform), and only with &#x60;carouselCards&#x60; (a 400 without them). Sets the creative&#39;s &#x60;link_data.multi_share_optimized&#x60;.  - &#x60;false&#x60;: keeps the cards in the order given. Meta then takes at most 5 cards, so &#x60;false&#x60; with more than 5 &#x60;carouselCards&#x60; is a 400. - &#x60;true&#x60;: Meta picks and reorders the cards for performance (up to 10). - Omitted: nothing is sent and Meta&#39;s default (&#x60;true&#x60;) applies. .</param>
        /// <param name="defaultLocale">Meta only. Language the top-level copy is written in (e.g. &#x60;en&#x60;, &#x60;pt_BR&#x60;), used by the &#x60;translations&#x60; default rule. Defaults to &#x60;en&#x60;. Meta rejects a language asset feed whose default rule carries no locales of its own. Must NOT also appear as an entry in &#x60;translations&#x60;..</param>
        /// <param name="translations">Meta only. Multi-language ads (Dynamic Language Optimization, the \&quot;Languages\&quot; toggle in Ads Manager): ONE ad with per-locale copy and, optionally, per-locale media. Social proof (likes/comments/shares) stays on a SINGLE post instead of splitting across one ad per language.  The ad&#39;s top-level copy is the DEFAULT for every locale you do NOT list, and counts as one of the language variants.  **Text does NOT inherit** (the opposite of what you might expect). Every entry needs its own &#x60;headline&#x60;, &#x60;body&#x60; AND &#x60;description&#x60;, all DISTINCT from each other and from the top-level copy. &#x60;description&#x60; is therefore effectively required on the ad whenever &#x60;translations&#x60; is present, though optional otherwise.  Why: Meta deduplicates identical strings in the asset feed, so two locales sharing a string collapse into one asset.  The create then fails with a misleading \&quot;Too few ... texts provided in asset creation\&quot; (subcode 1885817) naming a field that is present. We validate first and return a 400 naming the locale and field.  Do NOT list &#x60;defaultLocale&#x60; inside &#x60;translations&#x60;: Meta rejects the duplicate with \&quot;The language asset feed includes an unsupported targeting field\&quot; (subcode 1885985).  **Media DOES inherit** and is uploaded once when shared. &#x60;linkUrl&#x60; inherits too: each locale may name its own landing page, and unlisted locales fall back to the top-level &#x60;linkUrl&#x60;.  Meta enforces Dynamic Creative image dimensions on language feeds, so an &#x60;imageUrl&#x60; that works on a normal ad may fail with \&quot;The following images have invalid dimensions for Dynamic Creative\&quot; (subcode 1885558). Video is not affected.  Mutually exclusive with &#x60;dynamicCreative&#x60;, &#x60;placementAssets&#x60;, &#x60;carouselCards&#x60;, &#x60;existingCreativeId&#x60; and &#x60;creatives[]&#x60;: Meta allows one &#x60;asset_feed_spec&#x60; shape per creative. .</param>
        /// <param name="placementAssets">Meta only. Pins a SPECIFIC asset (image OR video) to each placement group on a SINGLE ad (e.g. a 9:16 on Stories/Reels and a 4:5 on Feed). The same thing Ads Manager produces with \&quot;different creative per placement\&quot;, mapped to the creative&#39;s &#x60;asset_feed_spec&#x60; + &#x60;asset_customization_rules&#x60;.  Deterministic pinning, NOT the auto-optimizing pool of &#x60;dynamicCreative&#x60; (mutually exclusive). Cannot be combined with &#x60;creatives[]&#x60; or top-level &#x60;bodies&#x60;/&#x60;headlines&#x60;/&#x60;descriptions&#x60; arrays.  Works on the legacy single shape AND the attach shape: &#x60;adSetId&#x60; + placementAssets adds one placement-customized ad to an existing ad set. To build N per-placement ads sharing one ad set, create the first normally and attach the rest.  **Text.** Each rule can override &#x60;headline&#x60;, &#x60;body&#x60; and &#x60;description&#x60; with one string per field. Omitted fields and unmatched placements use the top-level copy; &#x60;linkUrl&#x60; and &#x60;callToAction&#x60; remain shared. Zernio emits labelled text with &#x60;optimization_type: PLACEMENT&#x60;. Multiple text options rotating within a placement are not supported by this input.  **Placements.** Each rule&#39;s &#x60;placements&#x60; accepts the same fields as the top-level &#x60;placements&#x60; object; Meta enforces co-selection rules and returns an actionable error.  Meta controls text rendering by placement and format. Validation accepts these fields but does not prove that every field appears in delivery. Preview the ad, and put copy that must always be visible into the image or video itself.  &#x60;validateOnly: true&#x60; supports all-image placementAssets without uploading or creating anything. Video placement validation remains unsupported because it requires uploads.  **Media.** A block is all-image OR all-video, never mixed (Meta&#39;s asset_feed_spec carries one ad format). Exactly one catch-all default is required.  - Image mode: &#x60;defaultImageUrl&#x60; + &#x60;rules[].imageUrl&#x60;. - Video mode: &#x60;defaultVideoUrl&#x60; + &#x60;rules[].videoUrl&#x60;, with optional &#x60;thumbnailUrl&#x60;/&#x60;defaultThumbnailUrl&#x60; posters (Meta auto-generates them when omitted). .</param>
        /// <param name="audienceId">Custom audience ID for targeting.</param>
        /// <param name="campaignType">Google only. Performance Max requires assetGroup and Demand Gen requires demandGen; both are always created PAUSED. With &#x60;adSetId&#x60; it defaults to the ad group&#39;s own campaign type instead of display. (default to CampaignTypeEnum.Display).</param>
        /// <param name="locationTargetingType">Google only (400 elsewhere). Set on the new campaign; a request that joins an existing campaign (&#x60;existingCampaignId&#x60; or &#x60;adSetId&#x60;) returns 400, change that campaign with PUT /v1/ads/campaigns/{campaignId}/targeting instead. &#x60;presence&#x60; reaches only people in or regularly in the targeted locations..</param>
        /// <param name="assetGroup">assetGroup.</param>
        /// <param name="demandGen">demandGen.</param>
        /// <param name="keywords">Google Search only. Keywords on the new ad group; entries are strings (BROAD) or { text, matchType }. Editable later via PUT /v1/ads/{adId} targeting.keywords..</param>
        /// <param name="negativeKeywords">Google Search only; other platforms return 400. Ad-group-level negative keywords on the new ad group. Editable later via PUT /v1/ads/{adId} targeting.negativeKeywords..</param>
        /// <param name="campaignNegativeKeywords">Google Search only; other platforms return 400. Campaign-level negative keywords (campaign_criterion.negative), created alongside the ad group. Editable later via PUT /v1/ads/campaigns/{campaignId}/negative-keywords..</param>
        /// <param name="additionalHeadlines">Google Search RSA only. Extra text assets, as strings or objects with text and optional pinnedField. String input remains supported.  - The effective create lists, including primary text and after deduplication, must contain 3-15 headlines and 2-4 descriptions. Excess entries return 400. - Each headline is at most 30 characters (Google&#39;s limit). A longer one returns 400 naming the field and index (e.g. &#x60;additionalHeadlines[2]&#x60;); it is never truncated. - On Search the same limit applies to &#x60;headline&#x60; and &#x60;longHeadline&#x60; (30) and to &#x60;body&#x60; (90). .</param>
        /// <param name="additionalDescriptions">Google Search RSA only. Extra text assets, as strings or objects with text and optional pinnedField. Existing string input remains supported.  - The effective create lists, including primary text and deduplication, must contain 3-15 headlines and 2-4 descriptions; excess entries return 400. - Each description is at most 90 characters (Google&#39;s limit). A longer one returns 400 naming the field and index (e.g. &#x60;additionalDescriptions[2]&#x60;); it is never truncated. - On Search the same limit applies to &#x60;headline&#x60; and &#x60;longHeadline&#x60; (30) and to &#x60;body&#x60; (90). .</param>
        /// <param name="sitelinks">Google Search only. Sitelink assets to create and attach at the campaign level. Each entry becomes an Asset (with sitelink_asset + Asset.final_urls) plus a CampaignAsset link (field_type SITELINK).  Approval is async: Google reviews assets after creation; poll asset.policy_summary later to read the verdict.  Google requires at least two sitelinks to surface them on an ad; four or more is Google&#39;s own recommendation for maximum visibility. The response&#39;s creative.sitelinks[] echoes each input plus its Google resourceName. .</param>
        /// <param name="callouts">Google Search only. Short callout texts (max 25 chars each) that appear as non-clickable annotations under the ad, e.g. \&quot;Free shipping\&quot;, \&quot;24/7 support\&quot;. Each becomes one Asset (&#x60;callout_asset&#x60;) plus a CampaignAsset link with field_type CALLOUT. Response&#39;s creative.callouts[] echoes each input plus its Google resourceName. .</param>
        /// <param name="structuredSnippets">Google Search only. Structured snippets: one header from Google&#39;s predefined list plus 3-10 values (max 25 chars each). Each becomes one Asset (&#x60;structured_snippet_asset&#x60;) plus a CampaignAsset link with field_type STRUCTURED_SNIPPET. .</param>
        /// <param name="advantageAudience">Meta only. Controls the Advantage audience feature (targeting_automation). 0 &#x3D; disabled (default), 1 &#x3D; enabled. Meta Marketing API requires this field on all ad set creation requests..</param>
        /// <param name="attributionSpec">Meta only. Conversion attribution window for the ad set, mapping 1:1 to Meta&#39;s ad-set &#x60;attribution_spec&#x60;. Only honored for conversion goals (&#x60;conversions&#x60;, &#x60;lead_generation&#x60;, &#x60;app_promotion&#x60;); ignored for awareness/traffic/engagement. Omit to use Meta&#39;s default (&#x60;7-day click&#x60; + &#x60;1-day view&#x60;).  Meta enforces the valid combinations (invalid combos surface as a Meta 400):  - &#x60;VIEW_THROUGH&#x60;: only &#x60;windowDays: 1&#x60; (7d/28d view windows were removed Jan 2026). - &#x60;ENGAGED_VIDEO_VIEW&#x60;: only &#x60;1&#x60;, and only alongside &#x60;VIEW_THROUGH: 1&#x60;. - &#x60;CLICK_THROUGH: 28&#x60;: only on certain objectives.  Example: &#x60;[{ \&quot;eventType\&quot;: \&quot;CLICK_THROUGH\&quot;, \&quot;windowDays\&quot;: 7 }, { \&quot;eventType\&quot;: \&quot;VIEW_THROUGH\&quot;, \&quot;windowDays\&quot;: 1 }]&#x60; .</param>
        /// <param name="gender">Restrict the audience by gender. &#39;male&#39; targets men only, &#39;female&#39; targets women only, &#39;all&#39; (default) targets everyone. Applied on Meta, TikTok, Pinterest and Reddit. Ignored on Google, LinkedIn and X. (default to GenderEnum.All).</param>
        /// <param name="bidStrategy">Deprecated: send it inside &#x60;platformSpecificData&#x60; instead (Meta today; TikTok&#39;s nested shape is planned). The flat field keeps working during the deprecation window. Sending both shapes returns a 400.  Bid strategy applied to the ad set (Meta). Per platform:  - **OpenAI Ads:** only this flat field works (&#x60;platformSpecificData&#x60; is Meta/LinkedIn-only and returns 400 for OpenAI). &#x60;LOWEST_COST_WITH_BID_CAP&#x60; or &#x60;COST_CAP&#x60; with &#x60;bidAmount&#x60; sets a fixed bid (&#x60;fixed_bid&#x60;, the CPA bid on &#x60;conversions&#x60;). - **OpenAI Ads, automatic:** omitted or &#x60;LOWEST_COST_WITHOUT_CAP&#x60; uses OpenAI&#39;s Maximize Results (&#x60;maximize_clicks&#x60; for &#x60;traffic&#x60;, &#x60;maximize_conversions&#x60; for &#x60;conversions&#x60;). It needs &#x60;budgetType: daily&#x60;; a lifetime budget or the &#x60;awareness&#x60; goal returns 400. - **Reddit Ads:** flat field, applied to the new ad group. LOWEST_COST_WITHOUT_CAP or omitted &#x3D; automatic bidding (BIDLESS). LOWEST_COST_WITH_BID_CAP + &#x60;bidAmount&#x60; &#x3D; MANUAL_BIDDING with that bid. COST_CAP + &#x60;bidAmount&#x60; &#x3D; MAXIMIZE_VOLUME with that cap. Any other strategy returns 422 before anything is created. - **Google:** not deprecated (this flat field is Google&#39;s only shape), applied to the campaign this call creates. LOWEST_COST_WITHOUT_CAP &#x3D; Maximize Conversions. COST_CAP + bidAmount &#x3D; Target CPA. LOWEST_COST_WITH_MIN_ROAS + roasAverageFloor &#x3D; Target ROAS. - **Google, continued:** LOWEST_COST_WITH_BID_CAP + bidAmount &#x3D; Maximize Clicks with a CPC ceiling. portfolioBidStrategyId attaches a portfolio strategy instead. Omitted, the campaign falls back to a goal-based default. .</param>
        /// <param name="bidAmount">Deprecated: send it inside &#x60;platformSpecificData&#x60; instead (Meta today; TikTok&#39;s nested shape is planned). The flat field keeps working during the deprecation window; sending both shapes returns a 400.  Bid cap in WHOLE currency units (USD: 5 &#x3D; $5.00; JPY: 100 &#x3D; ¥100). Required when &#x60;bidStrategy&#x60; is &#x60;LOWEST_COST_WITH_BID_CAP&#x60; or &#x60;COST_CAP&#x60;.  Meta only: &#x60;bidAmount&#x60; WITHOUT &#x60;bidStrategy&#x60; requires &#x60;existingCampaignId&#x60; (400 otherwise). It sets the new ad set&#39;s cap under the joined campaign&#39;s COST_CAP / LOWEST_COST_WITH_BID_CAP parent; the strategy is inherited from the campaign. Restating bidStrategy here is accepted but has no effect on the ad set.  Rejected with 400 in &#x60;adSetId&#x60; attach mode, which inherits its cap from the platform. Use &#x60;PUT /v1/ads/ad-sets/{adSetId}&#x60; there instead. .</param>
        /// <param name="roasAverageFloor">Deprecated: send it inside &#x60;platformSpecificData&#x60; instead (Meta today; TikTok&#39;s nested shape is planned). The flat field keeps working during the deprecation window. Sending both shapes returns a 400.  Minimum ROAS as a decimal multiplier (e.g. 2.0 &#x3D; 2.0x ROAS). Required when &#x60;bidStrategy&#x60; is &#x60;LOWEST_COST_WITH_MIN_ROAS&#x60;; sending it without &#x60;bidStrategy&#x60; is a 400. Sent to Meta as &#x60;bid_constraints.roas_average_floor&#x60; × 10000.  Known gap: a CBO campaign&#39;s ROAS floor lives on the campaign only (set via &#x60;POST /v1/ads/campaigns&#x60;). There is no supported way to set it while joining a CBO campaign here. .</param>
        /// <param name="portfolioBidStrategyId">Google Search and Display only. Performance Max rejects portfolio bidding. Attach an existing portfolio bid strategy (numeric id from GET /v1/ads/bid-strategies) to the new campaign instead of a standard one. Exclusive with bidStrategy..</param>
